/* AVORA original frontend. No dependency on remote images, fonts or UI services. */
const $=s=>document.querySelector(s), e=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const state={token:sessionStorage.getItem('avora_token')||'',user:null,mode:localStorage.getItem('avora_mode')||'buyer',q:'',providers:[],requests:[],detail:null,loading:false};
const icon='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M10 29 32 11l22 18v25H10z" fill="none" stroke="currentColor" stroke-width="5" stroke-linejoin="round"/><path d="M25 54V36h14v18" fill="none" stroke="currentColor" stroke-width="4"/></svg>';
const go=(path)=>{location.hash='#'+path};
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>t.style.display='none',4800)}
async function api(url,opts={}){const h={'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(opts.headers||{})};let res=await fetch('/api'+url,{...opts,headers:h});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.detail||'Request failed');return data}
async function refresh(){try{const [p,r]=await Promise.all([api('/providers'),api('/requests')]);state.providers=p;state.requests=r;if(state.token)state.user=await api('/me')}catch(err){if(/Session expired|Sign in required/.test(err.message)){state.token='';state.user=null;sessionStorage.removeItem('avora_token')}else console.error(err)}}
const path=()=>decodeURIComponent(location.hash.slice(1)||'/');
function avoraBackRoute(route){
 const bits=route.split('/').filter(Boolean);
 if(bits[0]==='market'){
   if(bits[1]&&bits[2]==='product')return {url:'#/market/'+bits[1],text:'Back to storefront'};
   if(bits[1]&&bits[2]==='request')return {url:'#/market/'+bits[1]+'/product/'+bits[3],text:'Back to service'};
   if(bits[1]&&bits[2]==='edit')return {url:'#/market/'+bits[1]+'/manage',text:'Back to seller studio'};
   if(bits[1]&&bits[2]==='manage')return {url:'#/market/'+bits[1],text:'Back to storefront'};
   return {url:'#/explore',text:'Back to Explore'};
 }
 if(bits[0]==='shop')return {url:bits[2]==='product'?'#/shop/'+bits[1]:'#/provider/'+bits[1],text:'Back to collection'};
 if(bits[0]==='provider')return {url:'#/explore',text:'Back to Explore'};
 if(bits[0]==='enquiry')return {url:'#/messages',text:'Back to messages'};
 if(bits[0]==='requests'&&bits[1])return {url:'#/requests',text:'Back to opportunities'};
 if(route.startsWith('/market-order/'))return {url:'#/market-orders',text:'Back to orders'};
 if(route==='/market-bag')return {url:typeof marketState!=='undefined'&&marketState.lastShop?'#/market/'+marketState.lastShop:'#/explore',text:'Continue shopping'};
 if(route==='/demo-bag')return {url:'#/explore',text:'Back to Explore'};
 if(route==='/operations'||route==='/market-orders'||route==='/messages'||route==='/near'||route==='/settings')return {url:'#/dashboard',text:'Back to workspace'};
 if(route==='/dashboard')return {url:'#/',text:'Back to Home'};
 return {url:'#/',text:'Back to Home'};
}

function header(){return `<header class="top"><a class="brand" href="#/">${icon} AVORA</a><nav class="nav"><a href="#/explore">Explore</a><a href="#/explore?type=services">Services</a><a href="#/requests">Opportunities</a><a href="#/near">NEAR Coordination</a><a href="#/market-orders">Orders</a><a href="#/operations">Bookings & updates</a><a href="#/trust">Trust & Safety</a><a href="#/about">How it works</a></nav><div class="actions">${state.user?`<a class="btn ghost avora-top-identity" href="#/me/edit"><span class="avatar avora-mini-avatar">${userAvatar(state.user)}</span> My profile</a><a class="btn ghost" href="#/dashboard">My workspace</a><button class="btn" data-action="logout">Sign out</button>`:`<a class="btn ghost" href="#/signin">Sign in</a><a class="btn" href="#/signup">Join AVORA</a>`}</div></header>`}
function foot(){return `<footer class="footer"><div><b>AVORA</b><p>A human-centred community and commerce network.</p><small>Demo data is fictional. Payment status is never fabricated.</small></div><div><a href="#/terms">Terms & Conditions</a><a href="#/privacy">Privacy</a><a href="#/trust">Trust & Safety</a><a href="#/about">About</a></div></footer>`}
const demoProviderArtwork={
'Mpho Woodworks':'provider-mpho-cover.jpg',
'Anele Digital':'provider-anele-cover.jpg',
'Thabo Visuals':'provider-thabo-cover.jpg',
'Naledi Bakes':'provider-naledi-cover.jpg',
'BrightPath Plumbing':'provider-brightpath-cover.jpg',
'Pixel Harbor':'provider-pixel-cover.jpg',
'Sefako Prints':'provider-sefako-cover.jpg',
'Nala Community Courier':'provider-nala-cover.jpg',
'Dineo Home Care':'provider-dineo-cover.jpg',
'Tumi Learning':'provider-tumi-cover.jpg'
};
const providerImage=p=>{if(p.cover_url)return p.cover_url;if(p.owner_id==null&&demoProviderArtwork[p.name])return '/static/media/'+demoProviderArtwork[p.name];const raw=(p.name+' '+p.category+' '+p.kind+' '+p.skills).toLowerCase();if(/plumb|pipe|tap repair/.test(raw))return '/static/media/provider-brightpath-cover.jpg';if(/carpentry|wood|furniture/.test(raw))return '/static/media/provider-mpho-cover.jpg';if(/web|digital|software|frontend/.test(raw))return '/static/media/provider-anele-cover.jpg';if(/photo|creative|branding|visual/.test(raw))return '/static/media/provider-thabo-cover.jpg';if(/food|bakery|cake|catering/.test(raw))return '/static/media/provider-naledi-cover.jpg';if(/beauty|hair/.test(raw))return '/static/media/hair-1.jpg';if(/delivery|courier|logistics/.test(raw))return '/static/media/provider-nala-cover.jpg';if(/cleaning/.test(raw))return '/static/media/provider-dineo-cover.jpg';if(/tutor|learning|science|education/.test(raw))return '/static/media/provider-tumi-cover.jpg';if(/velora|fashion|clothing|dress|streetwear|sneakers|handbags/.test(raw))return '/static/media/velora-dress-1.jpg';if(/printing|packaging/.test(raw))return '/static/media/provider-sefako-cover.jpg';return '/static/media/web.webp'};
const businessAvatar=p=>p.avatar_url?`<img class="avora-avatar-photo" src="${e(p.avatar_url)}" alt="${e(p.name)} profile photo"/>`:`<span class="avora-avatar-placeholder" role="img" aria-label="Business has not uploaded a profile photo">✦</span>`;
const userAvatar=u=>u?.avatar_url?`<img class="avora-avatar-photo" src="${e(u.avatar_url)}" alt="Your profile photo"/>`:`<span class="avora-avatar-placeholder" aria-label="No profile photo uploaded">✦</span>`;
const uploadPhoto=async(file,kind,id)=>{if(!file)return;if(file.size>2200000)throw Error('Select a photo smaller than 2.2 MB');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});return api('/experience/images/'+kind+'/'+id,{method:'POST',body:JSON.stringify({data:raw})})};
const kinds=['Services','Digital services','Local services','Remote services','Products'];
const kindOptions=v=>kinds.map(k=>`<option value="${k}" ${v===k?'selected':''}>${k}</option>`).join('');
const providerExtraFields=(p={})=>`<div class="adaptive-fields" data-service-fields><div class="split"><div class="field"><label>Service area or delivery coverage</label><input name="service_area" maxlength="150" value="${e(p.service_area||'')}" placeholder="e.g. Johannesburg, 20 km; global remote"></div><div class="field"><label>Website (optional)</label><input name="website" type="url" value="${e(p.website||'')}" placeholder="https://example.com"></div></div><div class="field" data-kind="Products"><label>Shipping, pickup and returns approach</label><textarea name="delivery_info" maxlength="250" placeholder="Describe how products are delivered or collected">${e(p.delivery_info||'')}</textarea></div><div class="field" data-kind="Services|Digital services|Local services|Remote services"><label>Bookings, schedules and typical turnaround</label><textarea name="booking_info" maxlength="250" placeholder="Describe availability and how clients book">${e(p.booking_info||'')}</textarea></div></div>`;
function syncServiceFields(){document.querySelectorAll('[data-service-fields]').forEach(group=>{const form=group.closest('form');const kind=form?.querySelector('[name=kind]')?.value||'Services';group.querySelectorAll('[data-kind]').forEach(f=>{f.hidden=!f.dataset.kind.split('|').includes(kind);});const price=form?.querySelector('.price-label');if(price)price.textContent=kind==='Products'?'Starting product price (USD demo)':kind==='Digital services'?'Starting project price (USD demo)':'Starting service price (USD demo)';const cap=form?.querySelector('.capacity-label');if(cap)cap.textContent=kind==='Products'?'Available stock':'Available bookings / capacity';});}

const VELORA_IMAGES={
 'Burgundy Satin Cowl-Neck Dress':['velora-dress-1.jpg','velora-dress-2.jpg','velora-dress-3.jpg'],
 'Blush Street Sneakers':['velora-sneakers-1.jpg','velora-sneakers-2.jpg','velora-sneakers-3.jpg'],
 'Quilted Shoulder Bag':['velora-bag-1.jpg','velora-bag-2.jpg','velora-bag-3.jpg'],
 'Everyday Fashion Styling Bundle':['velora-dress-2.jpg']};
const veloraImg=n=>'/static/media/'+(VELORA_IMAGES[n]?.[0]||'velora-dress-1.jpg');
const fashionListingCard=l=>`<article class="velora-product"><div class="velora-product-photo" style="background-image:url('${veloraImg(l.title)}')"></div><div class="velora-product-content"><span class="eyebrow">ILLUSTRATIVE COLLECTION</span><h3>${e(l.title)}</h3><p>${e(l.description)}</p><div class="velora-product-price">$${e(l.price)} <small>USD demo price — no checkout</small></div></div></article>`;

function pcard(p){const img=providerImage(p);return `<article class="card provider"><div class="provider-cover" style="background-image:linear-gradient(180deg,rgba(9,12,13,.04),rgba(9,12,13,.35)),url('${img}')"><span class="provider-kind">${e(p.kind)}</span></div><div class="provider-body"><div class="head"><div class="avatar">${businessAvatar(p)}</div><div><h3>${e(p.name)}</h3><div class="meta">${e(p.category)} · ${e(p.city)}, ${e(p.country)}</div></div></div><p class="subtle">${e(p.bio)}</p><div><span class="tag ${p.verified?'ok':''}">${p.verified?'✓ Demo verified label':'Unverified'}</span> <span class="tag">${p.remote?'Remote available':'Local service'}</span></div><div class="foot"><span class="meta">★ ${p.rating?e(p.rating):'New'} · ${e(p.reviews)} sample ratings<br>From $${e(p.price)} (illustrative)</span><button class="btn outline small" data-action="profile" data-id="${p.id}">View profile →</button>${state.user&&p.owner_id===state.user.id?`<a class="btn ghost small" href="#/market/${p.id}/manage">Manage</a>`:''}</div></div></article>`}
/* Fashion discovery and the sample shopping bag are intentionally client-side: no fake purchases. */
const shopState={q:'',category:'All',sort:'featured',page:1};
let demoBag=[];
try{const b=JSON.parse(sessionStorage.getItem('avora_demo_bag')||'[]');if(Array.isArray(b))demoBag=b.filter(x=>Number.isInteger(x.id)&&Number.isInteger(x.qty)&&x.qty>0).slice(0,30)}catch(_){}
const saveDemoBag=()=>sessionStorage.setItem('avora_demo_bag',JSON.stringify(demoBag));
const fashionCategory=l=>/styling|service/i.test(l.kind)?'Styling':/dress/i.test(l.title)?'Dresses':/sneaker|shoe/i.test(l.title)?'Shoes':'Accessories';
const fashionImages=l=>(VELORA_IMAGES[l.title]||['velora-dress-1.jpg']).map(x=>'/static/media/'+x);
async function shopPage(pid){let detail;try{detail=await api('/providers/'+pid)}catch(err){return `<div class="page">${e(err.message)}</div>`}const isVelora=detail.name==='VELORA FASHION';const listings=(detail.listings||[]).filter(l=>l.kind.toLowerCase().includes('product')||isVelora);if(!isVelora)return `<div class="page"><a href="#/provider/${pid}">← Provider profile</a><h1>Storefront unavailable</h1><p>This mini storefront currently demonstrates VELORA FASHION.</p></div>`;
const term=shopState.q.toLowerCase().trim();let filtered=listings.filter(l=>(shopState.category==='All'||fashionCategory(l)===shopState.category)&&(!term||[l.title,l.description,fashionCategory(l)].join(' ').toLowerCase().includes(term)));if(shopState.sort==='price-low')filtered.sort((a,b)=>a.price-b.price);if(shopState.sort==='price-high')filtered.sort((a,b)=>b.price-a.price);if(shopState.sort==='name')filtered.sort((a,b)=>a.title.localeCompare(b.title));
return `<div class="fashion-shop"><div class="fashion-top"><a href="#/provider/${pid}" class="fashion-back">← AVORA marketplace</a><span>VELORA FASHION · DEMO COLLECTION</span><button class="fashion-bag-button" data-action="demo-bag" aria-label="Open demo bag">Bag (${demoBag.reduce((n,x)=>n+x.qty,0)})</button></div><section class="fashion-hero"><div class="fashion-hero-copy"><span class="eyebrow">THE VELORA EDIT / 2026</span><h1>Style the moment.</h1><p>Discover effortless outfits and everyday statement pieces. Search, filter, explore every angle, and build your sample bag.</p><span class="fashion-disclaimer">Demonstration catalogue · No real checkout</span></div><div class="fashion-hero-pictures"><img src="/static/media/velora-dress-1.jpg" alt="Burgundy dress"/><img src="/static/media/velora-bag-1.jpg" alt="Quilted shoulder bag"/></div></section><div class="fashion-benefits"><span>✦ Curated edits</span><span>✦ Style inspiration</span><span>✦ Demo bag</span><span>✦ AVORA opportunity network</span></div><section class="fashion-shop-body"><div class="fashion-heading"><div><span class="eyebrow">SHOP THE COLLECTION</span><h2>Find your new favourite.</h2></div><span>${filtered.length} styles</span></div><form class="fashion-controls" data-form="fashion-search"><input name="q" aria-label="Search VELORA products" placeholder="Search dresses, shoes, bags, styling…" value="${e(shopState.q)}"/><select name="category" aria-label="Filter by category">${['All','Dresses','Shoes','Accessories','Styling'].map(cat=>`<option value="${cat}" ${shopState.category===cat?'selected':''}>${cat==='All'?'All categories':cat}</option>`).join('')}</select><select name="sort" aria-label="Sort products">${[['featured','Featured'],['price-low','Price: low to high'],['price-high','Price: high to low'],['name','Name A–Z']].map(([v,label])=>`<option value="${v}" ${shopState.sort===v?'selected':''}>${label}</option>`).join('')}</select><button class="btn">Apply filters</button><button type="button" class="btn outline" data-action="fashion-reset">Clear</button></form><div class="fashion-products">${filtered.map(l=>`<article class="fashion-product"><a class="fashion-image" href="#/shop/${pid}/product/${l.id}"><img src="${fashionImages(l)[0]}" alt="${e(l.title)}" loading="lazy"/><span class="fashion-picture-count">${fashionImages(l).length} photos</span></a><div class="fashion-product-body"><span class="eyebrow">${fashionCategory(l)}</span><h3>${e(l.title)}</h3><p>${e(l.description)}</p><div class="fashion-product-bottom"><b>$${e(l.price)} <small>USD / demo</small></b><a class="btn small outline" href="#/shop/${pid}/product/${l.id}">View details</a></div></div></article>`).join('')||'<div class="panel empty">No styles match. Clear filters to see the full collection.</div>'}</div></section></div>`}
async function shopProduct(pid,lid){let p;try{p=await api('/providers/'+pid)}catch(err){return `<div class="page">${e(err.message)}</div>`}const l=(p.listings||[]).find(x=>x.id===+lid);if(p.name!=='VELORA FASHION'||!l)return '<div class="page">Style not found.</div>';const photos=fashionImages(l);return `<div class="fashion-shop"><div class="fashion-top"><a href="#/shop/${pid}">← Back to VELORA collection</a><span>PRODUCT DETAILS / DEMO</span><button class="fashion-bag-button" data-action="demo-bag">Bag (${demoBag.reduce((n,x)=>n+x.qty,0)})</button></div><div class="fashion-detail"><div class="fashion-gallery"><img class="fashion-main-image" id="fashion-main-photo" src="${photos[0]}" alt="${e(l.title)}"/><div class="fashion-thumbnails">${photos.map((src,i)=>`<button class="fashion-thumb ${i===0?'active':''}" type="button" data-action="fashion-image" data-src="${e(src)}"><img src="${src}" alt="View ${e(l.title)} angle ${i+1}"/></button>`).join('')}</div></div><div class="fashion-detail-info"><span class="eyebrow">VELORA FASHION / ${fashionCategory(l)}</span><h1>${e(l.title)}</h1><p class="fashion-price">$${e(l.price)} <small>USD · illustrative</small></p><p class="subtle">${e(l.description)}</p><div class="fashion-form"><label>Size or option<select id="fashion-size">${(/sneaker/i.test(l.title)?['UK 3','UK 4','UK 5','UK 6','UK 7','UK 8','UK 9']:/dress/i.test(l.title)?['XS','S','M','L','XL']:['One size']).map(v=>`<option>${v}</option>`).join('')}</select></label><label>Quantity<input type="number" id="fashion-quantity" min="1" max="10" value="1"/></label><button class="btn" data-action="demo-bag-add" data-id="${l.id}" data-provider="${pid}">Add to sample bag</button></div><div class="notice">This is sample merchandise. Adding it to the bag does not reserve stock, charge you, or start a real checkout.</div><a href="#/shop/${pid}" class="link">Continue browsing →</a></div></div></div>`}
function demoBagView(){const velora=state.providers.find(p=>p.name==='VELORA FASHION');const total=demoBag.reduce((n,x)=>n+x.qty*x.price,0);return `<div class="page narrow"><a class="link" href="#/shop/${velora?.id||''}">← Back to VELORA</a><h1 class="page-title">Your sample bag</h1><p class="subtle">A realistic shopping-bag preview, not a payment flow.</p><div class="panel">${demoBag.map((x,i)=>`<div class="fashion-bag-line"><img src="${fashionImages({title:x.title})[0]}" alt="${e(x.title)}"/><div><strong>${e(x.title)}</strong><p class="meta">${e(x.size)} · Qty ${x.qty}</p><p>$${x.price*x.qty} USD</p></div><button class="btn ghost small" data-action="demo-bag-remove" data-index="${i}">Remove</button></div>`).join('')||'<p class="subtle">Your bag is empty. Browse the collection to add a style.</p>'}<div class="fashion-total">Sample subtotal <strong>$${total} USD</strong></div><div class="notice">Checkout disabled for sample inventory. No real merchant owns these demonstration listings.</div></div></div>`}
async function enquiryList(){if(!state.user)return mustSign();let threads;try{threads=await api('/enquiries')}catch(err){return shell(`<p>${e(err.message)}</p>`)}return shell(`<div class="workspace-heading"><span class="eyebrow">PRIVATE MESSAGING</span><h1 class="page-title">Messages and requests</h1><p class="subtle">A new conversation starts as a request. The receiving business decides whether to accept it before either participant can send follow-up messages.</p></div><div class="panel"><div class="section-head"><h2>Conversations</h2><span class="tag">${threads.filter(t=>t.status==='pending').length} pending</span></div>${threads.map(t=>`<a class="inbox-line" href="#/enquiry/${t.id}"><span class="inbox-dot"></span><div><strong>${e(t.subject)}</strong><p class="meta">${e(t.provider_name)} · ${e(t.buyer_name)}</p><p class="subtle">${e((t.last_message||'').slice(0,130))}</p></div><span class="tag ${t.status==='accepted'?'ok':''}">${e(t.status||'accepted')}</span></a>`).join('')||'<div class="empty">No messages yet. Browse a registered provider and select Request conversation.</div>'}</div><div class="panel" style="margin-top:18px"><h2>Project discussions</h2>${state.requests.filter(r=>r.buyer_id===state.user.id).map(r=>`<div class="list-item"><b>${e(r.title)}</b><a class="btn small outline" href="#/requests/${r.id}">View responses</a></div>`).join('')||'<p class="subtle">Project conversations appear after an accepted proposal.</p>'}</div>`) }
async function enquiryConversation(id){if(!state.user)return mustSign();let t;try{t=await api('/enquiries/'+id)}catch(err){return shell(`<p>${e(err.message)}</p>`)}const owner=t.owner_id===state.user.id;const status=t.status||'accepted';return shell(`<a href="#/messages" class="link">← All messages</a><div class="workspace-heading"><h1 class="page-title">${e(t.subject)}</h1><p class="subtle">${e(t.provider_name)} · ${e(t.buyer_name)} · ${e(status)}</p></div><div class="panel"><div class="conversation-status ${status}"><strong>${status==='pending'?'Message request awaiting acceptance':status==='declined'?'Request declined':'Conversation accepted'}</strong><p>${status==='pending'?'The provider can accept or decline this request. No further messages may be sent until then.':status==='declined'?'This message request has been closed.':'Both participants may now exchange messages.'}</p>${status==='pending'&&owner?`<div class="form-actions"><button class="btn" data-action="enquiry-decide" data-id="${t.id}" data-decision="accepted">Accept message request</button><button class="btn outline" data-action="enquiry-decide" data-id="${t.id}" data-decision="declined">Decline</button></div>`:''}</div><div class="chat fashion-chat">${t.messages.map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}"><small>${e(m.sender_name)}</small><p>${e(m.body)}</p></div>`).join('')}</div>${status==='accepted'?`<form data-form="enquiry-reply" data-enquiry="${t.id}" class="fashion-message-form"><label for="enquiry-message">Write a message</label><textarea id="enquiry-message" name="body" required minlength="1" maxlength="1500" placeholder="Ask about availability, scope or next steps…"></textarea><button class="btn">Send securely</button></form>`:''}</div>`)}
function startEnquiry(pid){const p=state.providers.find(x=>x.id===+pid);if(!p)return '<div class="page">Provider not found.</div>';if(!state.user)return mustSign();if(p.owner_id==null)return `<div class="page narrow"><a href="#/provider/${pid}" class="link">← Back</a><div class="panel"><h2>Example business</h2><p>This is a fictional example without a real person to receive messages. Post an open service request instead.</p><a href="#/requests/new" class="btn">Post a service request</a></div></div>`;if(p.owner_id===state.user.id)return `<div class="page narrow"><div class="notice">You cannot message your own provider account.</div></div>`;return shell(`<a href="#/provider/${pid}" class="link">← Back to ${e(p.name)}</a><h1 class="page-title">Message ${e(p.name)}</h1><p class="subtle">Ask about a service, price, availability, or custom project.</p><div class="panel narrow"><form data-form="enquiry-new" data-provider="${pid}"><div class="field"><label>Enquiry subject</label><input name="subject" minlength="4" maxlength="140" required value="Service enquiry for ${e(p.category)}"/></div><div class="field"><label>Your message</label><textarea name="message" minlength="10" maxlength="1500" required placeholder="Hello, I'm interested in your services. Could you tell me about availability and pricing?"></textarea></div><button class="btn">Send enquiry</button></form></div>`)}
function landing(){return `<div class="page"><section class="hero hero-rich"><div class="hero-copy"><span class="eyebrow hero-kicker">AI + HUMAN APPROVAL + NEAR TESTNET</span><h1>An opportunity is bigger<br><em>than one business.</em></h1><p>Find the right people, form a trusted team, recover when plans change, and verify testnet payments. AVORA turns the marketplace into a coordinated opportunity network for products, services, and independent professionals.</p><form class="searchbar" data-form="search"><input name="q" aria-label="Search AVORA" placeholder="A carpenter, a web developer, a birthday cake…"><button class="btn">Explore →</button></form><div class="buttons"><a href="#/requests/new" class="btn gold">Post a request</a><a href="#/near" class="btn outline light">Explore NEAR coordination</a></div><div class="hero-points"><span>Buyer + provider workspaces</span><span>AI-assisted team formation</span><span>NEAR testnet verification</span></div></div><div class="hero-visual"><article class="visual-card large" style="background-image:linear-gradient(180deg,rgba(7,10,11,.08),rgba(7,10,11,.48)),url('/static/media/web.webp')"><div><span class="tag dark">Digital services</span><h3>Build cross-functional teams</h3><p>Developers, makers, tutors, and local providers can respond together.</p></div></article><div class="visual-stack"><article class="visual-card small" style="background-image:linear-gradient(180deg,rgba(7,10,11,.05),rgba(7,10,11,.45)),url('/static/media/carpentry.webp')"><div><span class="tag dark">Local trades</span><h3>Real-world services</h3></div></article><article class="visual-card small" style="background-image:linear-gradient(180deg,rgba(7,10,11,.05),rgba(7,10,11,.45)),url('/static/media/bakery.webp')"><div><span class="tag dark">Independent makers</span><h3>Products & events</h3></div></article></div></div></section><section><div class="section-head"><div><span class="eyebrow">DISCOVER YOUR WAY</span><h2>Everything starts with a need.</h2><p>Use AVORA like a polished consumer marketplace, then move into coordinated opportunities when one business is not enough.</p></div></div><div class="tiles tiles-visual">${[['/static/media/delivery.webp','Local community','People and businesses nearby'],['/static/media/web.webp','Freelance & digital','Remote professional expertise'],['/static/media/tutoring.webp','Services','From carpentry to tutoring'],['/static/media/bag-1.jpg','Products & makers','Independent sellers and shops']].map(t=>`<a href="#/explore" class="tile tile-visual" style="background-image:linear-gradient(180deg,rgba(10,14,15,.08),rgba(10,14,15,.52)),url('${t[0]}')"><div class="tile-content"><h3>${t[1]}</h3><p>${t[2]}</p></div></a>`).join('')}</div></section><section class="section-head"><div><span class="eyebrow">COMMUNITY FIRST</span><h2>Discover independent professionals.</h2><p>Sample profiles for exploring the concept, not active vetted businesses.</p></div><a class="link" href="#/explore">Browse all →</a></section><div class="provider-grid">${state.providers.slice(0,3).map(pcard).join('')}</div><div class="split" style="margin-top:25px"><div class="panel panel-spotlight"><span class="eyebrow">ONE IDENTITY · TWO ROLES</span><h2>Switch when life changes.</h2><p class="subtle">Buy something today. Offer your skills tomorrow. AVORA gives you Buyer and Provider workspaces without creating separate accounts.</p><a class="btn" href="#/signup">Create your account</a></div><div class="panel panel-spotlight"><span class="eyebrow">BUILT FOR TRUST</span><h2>AVORA Guardian</h2><p class="subtle">Verified payments, evidence-led reporting, review eligibility, and clear agreements. Fraud signals support investigation; they do not automatically prove wrongdoing.</p><a class="btn ghost" href="#/trust">Explore safety</a></div></div><section class="velora-feature"><div class="velora-feature-art"><img src="/static/media/velora-dress-1.jpg" alt="Burgundy satin dress"><img src="/static/media/velora-sneakers-1.jpg" alt="Blush fashion sneakers"><img src="/static/media/velora-bag-1.jpg" alt="Quilted handbag"></div><div class="velora-feature-copy"><span class="eyebrow">FEATURED FASHION SHOWCASE</span><h2>Meet VELORA FASHION.</h2><p>Trend-inspired dresses, accessories, and shoes. A fashion storefront demonstrating how AVORA connects products with photographers, couriers, and independent collaborators.</p><span class="velora-preview-label">Sample shop · Not available for checkout</span><div class="form-actions"><a class="btn" href="#/provider/${state.providers.find(p=>p.name==='VELORA FASHION')?.id||''}">Explore VELORA →</a><a class="btn outline" href="#/near">Explore coordination</a></div></div></section><section class="landing-stripe landing-stripe-rich"><span class="eyebrow">BEYOND A MARKETPLACE</span><h2>Small businesses can do more together.</h2><p class="subtle">An AI-powered coalition planner helps independent providers explore a shared opportunity, evaluate capacity, estimate costs, and prepare for NEAR-backed coordination before anyone agrees to participate.</p><a href="#/requests" class="btn">Discover opportunities →</a></section></div>`}
function signin(signup=false){return `<div class="auth-shell"><div class="auth-art"><span class="eyebrow">A COMMUNITY THAT WORKS TOGETHER</span><h1>${signup?'Make room for what comes next.':'Good to have you back.'}</h1><p>Discover services, offer your skills and manage trusted collaborations. One account. Two workspaces.</p><div style="margin-top:32px;color:#e4c9d7">✦ Local opportunity &nbsp;&nbsp; ✦ Global reach &nbsp;&nbsp; ✦ Human-centred trust</div></div><div class="auth-form"><div class="panel"><span class="eyebrow">${signup?'GET STARTED':'SIGN IN'}</span><h1 class="page-title">${signup?'Join AVORA':'Welcome back'}</h1><p class="subtle">${signup?'Your account can switch between buying and offering services.':'Continue your projects, discoveries and conversations.'}</p><form data-form="${signup?'signup':'signin'}">${signup?`<div class="field"><label>Your name</label><input name="name" minlength="2" required placeholder="Your name"></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input name="password" type="password" ${signup?'minlength="12"':''} required placeholder="${signup?'At least 12 characters':'Your password'}"></div>${signup?'<p class="hint">By creating an account you accept our <a href="#/terms">terms</a> and acknowledge our <a href="#/privacy">privacy notice</a>.</p>':''}<button class="btn" style="width:100%">${signup?'Create account':'Sign in'} →</button></form><p class="subtle">${signup?'Already registered? <a href="#/signin">Sign in</a>':'New to AVORA? <a href="#/signup">Create account</a>'}</p><div class="notice">This local prototype has no email verification or OAuth provider enabled. Do not use real personal data or passwords.</div></div></div></div>`}
const sideLinks=()=>state.mode==='buyer'?[['⌂','Home','/dashboard'],['⌕','Explore','/explore'],['＋','Post a request','/requests/new'],['▤','My requests','/requests'],['✉','Messages','/messages'],['▣','Orders','/market-orders'],['⚙','Settings','/settings'],['♧','Trust centre','/trust']]:[['⌂','Overview','/dashboard'],['▣','My storefront','/provider/new'],['◇','Opportunities','/requests'],['✉','Messages','/messages'],['▣','Orders','/market-orders'],['♧','Trust centre','/trust'],['⚙','Settings','/settings']];
function shell(content){const sel=path();return `<div class="shell"><aside class="sidebar"><div class="label">WORKSPACE</div><select id="workspace" aria-label="Switch workspace"><option value="buyer" ${state.mode==='buyer'?'selected':''}>Buyer</option><option value="provider" ${state.mode==='provider'?'selected':''}>Provider</option></select><a class="side-link ${sel==='/near'?'active':''}" href="#/near">◇ &nbsp;NEAR Coordination</a>${sideLinks().map(([ic,name,route])=>`<a class="side-link ${sel===route?'active':''}" href="#${route}">${ic} &nbsp;${name}</a>`).join('')}</aside><main class="content">${content}</main></div>`}
function dashboard(){let provider=state.mode==='provider';return shell(`<div class="welcome"><span class="eyebrow">${provider?'PROVIDER':'BUYER'} WORKSPACE</span><h1>Good to see you, ${e(state.user.name.split(' ')[0])}.</h1><p class="subtle">${provider?'Present your work, discover opportunities, and make meaningful connections.':'Find services, post requests, and manage your community connections.'}</p><a class="btn" href="#/${provider?'provider/new':'requests/new'}">${provider?'Create provider profile':'Post a request'} →</a></div><div class="stats"><div class="card stat"><span class="subtle">${provider?'My businesses':'Available providers'}</span><strong>${provider?state.user.businesses.length:state.providers.length}</strong></div><div class="card stat"><span class="subtle">Open opportunities</span><strong>${state.requests.filter(x=>x.status==='open').length}</strong></div><div class="card stat"><span class="subtle">Your requests</span><strong>${state.requests.filter(x=>x.buyer_id===state.user.id).length}</strong></div></div><div class="section-head"><h2>${provider?'Your businesses':'Recommended for you'}</h2><a class="link" href="#/${provider?'provider/new':'explore'}">${provider?'Add another':'See all'} →</a></div>${provider?`<div class="provider-grid">${state.user.businesses.map(pcard).join('')||'<div class="panel">You have no provider profile yet. Create one to start offering services.</div>'}</div>`:`<div class="provider-grid">${state.providers.slice(0,3).map(pcard).join('')}</div>`}<div class="section-head"><h2>Recent opportunities</h2><a href="#/requests" class="link">View all →</a></div><div class="panel">${state.requests.slice(0,4).map(item=>`<div class="list-item"><div><h3>${e(item.title)}</h3><div class="meta">${e(item.city)} · $${item.budget} budget · ${e(item.status)}</div></div><a class="btn ghost small" href="#/requests/${item.id}">View →</a></div>`).join('')||'<p class="subtle">No requests yet. Post the first one!</p>'}</div>`) }
function explore(){let q=state.q;return `<div class="page"><span class="eyebrow">DISCOVER AVORA</span><h1 class="page-title">Find the right people for your next idea.</h1><p class="subtle">Explore real categories with illustrative provider records. Provider and review data in this demo are seeded examples.</p><form data-form="search" class="toolbar"><input name="q" value="${e(q)}" placeholder="Try web development, carpentry, catering…" aria-label="Search providers"><select name="sort"><option value="recommended">Recommended</option><option value="rating">Highest rated</option><option value="price">Lowest sample price</option><option value="new">Emerging</option></select><button class="btn">Search</button></form><div class="provider-grid" id="results">${state.providers.filter(p=>!q||(p.name+' '+p.category+' '+p.bio+' '+p.skills).toLowerCase().includes(q.toLowerCase())).map(pcard).join('')||'<div class="panel empty">No results. Try a broader search.</div>'}</div></div>`}
async function profile(id){const p=state.providers.find(x=>x.id===+id);if(!p)return `<div class="page">Provider not found.</div>`;const img=providerImage(p);let veloraListings=[];if(p.name==='VELORA FASHION'&&p.owner_id==null){try{const detail=await api('/providers/'+p.id);veloraListings=detail.listings||[]}catch(err){console.error(err)}}return `<div class="page narrow"><a class="link" href="#/explore">← Back to explore</a><div class="panel provider-profile" style="margin-top:22px"><div class="provider-profile-cover" style="background-image:linear-gradient(180deg,rgba(8,11,12,.15),rgba(8,11,12,.55)),url('${img}')"></div><div class="provider-profile-inner"><div class="head" style="display:flex;gap:20px;align-items:center"><div class="avatar avora-avatar-large">${businessAvatar(p)}</div><div><span class="eyebrow">${e(p.category)}</span><h1 class="page-title">${e(p.name)}</h1><p class="meta">${e(p.city)}, ${e(p.country)} · ${p.remote?'Remote services available':'Local services'} · ${p.verified?'Demo verification marker':'Unverified'}</p></div></div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>About this provider</h3><p class="subtle">${e(p.bio)}</p>${p.website?`<p><a class="link" href="${e(p.website)}" target="_blank" rel="noopener noreferrer">Business website ↗</a></p>`:''}${p.service_area?`<p class="meta">Service area: ${e(p.service_area)}</p>`:''}${p.delivery_info?`<p class="meta">Delivery: ${e(p.delivery_info)}</p>`:''}${p.booking_info?`<p class="meta">Booking: ${e(p.booking_info)}</p>`:''}<h3>Experience and services</h3><p class="subtle">${e(p.skills.split(',').join(' · '))}</p><p>★ ${p.rating||'New'} · ${p.reviews} illustrative reviews · starting at $${p.price} (sample data)</p><div class="form-actions">${state.user&&p.owner_id===state.user.id?`<a class="btn outline" href="#/provider/${p.id}/edit">Edit profile and photos</a>`:''}<a class="btn" href="#/market/${p.id}">Browse products & services →</a>${p.name==='VELORA FASHION'?`<a class="btn" href="#/shop/${p.id}">Shop VELORA collection →</a>`:p.owner_id!=null?`<a class="btn" href="#/provider/${p.id}/message">Message provider →</a>`:`<a class="btn" href="#/requests/new">Post a service request</a>`}<button class="btn outline" data-action="report" data-id="${p.id}">Report a concern</button></div>${p.name==='VELORA FASHION'&&p.owner_id==null?`<section class="velora-collection"><div class="velora-heading"><div><span class="eyebrow">THE VELORA EDIT</span><h2>Discover the collection.</h2><p>Explore an interactive mini fashion shop: search, filter, product details and sample bag.</p></div><span class="velora-preview-label">Demonstration only</span></div><div class="form-actions"><a class="btn" href="#/shop/${p.id}">Open VELORA Shop →</a></div><div class="velora-products">${veloraListings.map(fashionListingCard).join('')}</div><div class="notice">This is a sample store. Prices and inventory are illustrative. No merchant account owns it, so checkout is intentionally disabled. Sign in and register your own provider business to create a real profile.</div></section>`:''}<div class="notice">Verification badges and historical ratings belong to demonstration records, not independently checked real businesses.</div></div></div></div>`}
function requestForm(){if(!state.user)return mustSign();return shell(`<span class="eyebrow">START WITH WHAT YOU NEED</span><h1 class="page-title">Post a request</h1><p class="subtle">Describe a product, service or project. Providers can propose an offer and you remain in control.</p><div class="panel narrow"><form data-form="request"><div class="field"><label>What do you need?</label><input name="title" required minlength="5" placeholder="A website for my bakery"></div><div class="field"><label>Describe your goal</label><textarea name="description" required minlength="12" placeholder="Include your requirements, preferred outcome, and any relevant context."></textarea></div><div class="split"><div class="field"><label>Category</label><select name="category"><option>Web development</option><option>Carpentry</option><option>Creative</option><option>Food</option><option>Events</option><option>Cleaning</option><option>Other services</option></select></div><div class="field"><label>City or community</label><input name="city" required value="Johannesburg"></div></div><div class="split"><div class="field"><label>Maximum total budget (USD demo)</label><input name="budget" type="number" min="1" value="500" required></div><div class="field"><label>Number of units / deliverables</label><input name="quantity" type="number" min="1" value="1" required></div></div><label class="subtle"><input name="remote" type="checkbox"> Remote providers also welcome</label><div class="form-actions"><button class="btn">Publish request</button><a href="#/dashboard" class="btn ghost">Cancel</a></div></form></div>`)}
function requests(){return shell(`<span class="eyebrow">OPPORTUNITIES</span><h1 class="page-title">Community requests</h1><p class="subtle">Discover opportunities or manage your own requests. Quotes from other provider accounts require a registered profile.</p><div class="form-actions"><a class="btn" href="#/requests/new">+ Post a request</a></div><div class="panel" style="margin-top:18px">${state.requests.map(r=>`<div class="list-item"><div><h3>${e(r.title)}</h3><p class="meta">${e(r.buyer_name)} · ${e(r.city)} · ${r.quantity} unit(s) · $${r.budget} budget · ${e(r.status)}</p></div><a class="btn ghost small" href="#/requests/${r.id}">Open →</a></div>`).join('')||'<div class="empty">No requests yet. Start with one, then test AVORA’s coalition planner.</div>'}</div>`)}
async function detailRequest(id){if(!state.user)return mustSign();let r;try{r=await api('/requests/'+id)}catch(err){return `<div class="page">${e(err.message)}</div>`}const mine=r.buyer_id===state.user.id;const match=mine?await api('/experience/requests/'+r.id+'/suggestions').catch(()=>({providers:[],mode:'rules_only'})):{providers:[]};const owns=state.user.businesses||[];return shell(`<span class="eyebrow">PROJECT WORKSPACE · #${r.id}</span><h1 class="page-title">${e(r.title)}</h1><p class="subtle">Posted by ${e(r.buyer_name)} · ${e(r.city)} · ${r.quantity} unit(s) · Budget $${r.budget} USD · ${e(r.status)}</p><div class="split"><div><div class="panel"><h3>Project brief</h3><p class="subtle">${e(r.description)}</p><h3>Interested providers and proposals</h3>${r.proposals.map(p=>`<div class="list-item"><div><b>${e(p.provider_name)}</b><p class="meta">$${p.amount} · ${e(p.status)} · ${e(p.note)}</p></div>${mine&&r.status==='open'?`<button class="btn small" data-action="accept" data-id="${p.id}">Accept</button>`:''}</div>`).join('')||'<p class="subtle">No quotes yet.</p>'}</div>${!mine&&owns.length?`<div class="panel" style="margin-top:16px"><h3>Respond to this request</h3><p class="subtle">Your proposal is private to the buyer until they choose to accept it. No payments or commitments are automatic.</p><form data-form="proposal" data-request="${r.id}"><div class="field"><label>Which business?</label><select name="provider_id">${owns.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label>Total price in USD</label><input name="amount" type="number" min="1" required></div><div class="field"><label>Scope and commitments</label><textarea name="note" required minlength="4"></textarea></div><button class="btn">Send quote</button></form></div>`:''}${mine?`<div class="panel" style="margin-top:16px"><h3>NEAR testnet payment protection</h3><p class="subtle">Accepted quotes describe the proposed scope in illustrative USD. Actual payment allocation and settlement require provider consent, buyer approval and NEAR testnet verification in the NEAR Coordination workspace. No card checkout or automatic charge is available.</p><a class="btn" href="#/near">Open NEAR Coordination →</a></div>`:''}</div><div><div class="panel"><h3>Provider recommendations</h3>${mine?`<p class="subtle">Matches use request skills, category, location and remote availability. These are rules-based until an AI model is configured; providers must opt in.</p>${match.providers.map(p=>`<div class="recommendation"><div class="avatar">${businessAvatar(p)}</div><div><strong>${e(p.name)}</strong><p class="meta">${e(p.category)} · ${e(p.city)} · Match score ${e(p.match_score)}</p></div><a href="#/provider/${p.id}" class="btn outline small">View</a></div>`).join('')||'<p class="subtle">No registered providers match yet. Your request remains open to interested sellers.</p>'}`:''}<h3>AVORA Intelligence</h3><p class="subtle">Capacity-aware matching, a deterministic coalition allocation and optional real AI explanations. No merchant is committed by an algorithm.</p><button class="btn" data-action="assemble" data-id="${r.id}">Assemble opportunity →</button><div id="intelligence" style="margin-top:14px"></div></div><div class="panel" style="margin-top:16px"><h3>Project conversation</h3><div class="chat">${r.messages.map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}"><small>${e(m.sender_name)}</small>${e(m.body)}</div>`).join('')||'<p class="subtle">Messages become available to the buyer and participating providers.</p>'}</div>${mine||r.proposals.some(p=>p.provider_owner===state.user.id&&p.status==='accepted')?`<form data-form="message" data-request="${r.id}" class="form-actions"><input class="input" style="flex:1" name="body" required maxlength="1500" placeholder="Write a message…"><button class="btn">Send</button></form>`:''}</div><div class="panel" style="margin-top:16px"><h3>Guardian</h3><p class="subtle">Flag suspicious off-platform payment attempts. Warnings are signals, not fraud verdicts.</p><button class="btn ghost" data-action="guardian" data-id="${r.id}">Run safety check</button><div id="guardian"></div></div></div></div>`)}
function providerForm(){if(!state.user)return mustSign();return shell(`<div class="workspace-heading"><span class="eyebrow">BUSINESS STUDIO · STEP 1 OF 3</span><h1 class="page-title">Create your business profile</h1><p class="subtle">Describe what you offer. The fields adjust for physical products, local services, and remote digital work. You can edit everything later.</p></div><div class="panel profile-editor"><form data-form="provider"><div class="form-section"><span class="eyebrow">01 · BUSINESS IDENTITY</span><div class="split"><div class="field"><label>Business or professional name</label><input name="name" required minlength="2" maxlength="70" placeholder="e.g. Nova Digital Studio"></div><div class="field"><label>Primary category</label><input name="category" list="avora-categories" required placeholder="e.g. Web development"><datalist id="avora-categories"><option value="Web development"><option value="Cleaning"><option value="Carpentry"><option value="Plumbing"><option value="Tutoring"><option value="Design"><option value="Photography"><option value="Catering"><option value="Fashion"><option value="Printing"><option value="Logistics"><option value="Beauty"></datalist></div></div><div class="field"><label>What do you offer?</label><select name="kind" data-adapt-kind>${kindOptions('Services')}</select></div></div><div class="form-section"><span class="eyebrow">02 · LOCATION & AVAILABILITY</span><div class="split"><div class="field"><label>City</label><input name="city" required placeholder="e.g. Johannesburg"></div><div class="field"><label>Country</label><input name="country" required value="South Africa"></div></div><label class="subtle"><input type="checkbox" name="remote"> Available to serve customers remotely</label>${providerExtraFields()}</div><div class="form-section"><span class="eyebrow">03 · YOUR EXPERTISE</span><div class="field"><label>About your work</label><textarea name="bio" required minlength="10" maxlength="900" placeholder="Explain what makes your work valuable, your experience, and who you help."></textarea></div><div class="field"><label>Skills, products or specialties (comma-separated)</label><input name="skills" required maxlength="300" placeholder="Responsive websites, React, accessibility"></div><div class="split"><div class="field"><label class="price-label">Starting sample price (USD)</label><input name="price" type="number" min="0" max="1000000" value="100" required></div><div class="field"><label class="capacity-label">Available capacity</label><input name="capacity" type="number" min="1" value="5" required></div></div></div><div class="notice">Your business starts unverified. Once registered, upload a logo/photo and cover image from Edit business profile, then publish individual listings in Store manager.</div><div class="form-actions"><button class="btn">Create business and continue →</button><a class="btn ghost" href="#/dashboard">Cancel</a></div></form></div>`)}
async function editBusiness(pid){if(!state.user)return mustSign();let p;try{p=await api('/providers/'+pid)}catch(err){return shell(`<p>${e(err.message)}</p>`)}if(p.owner_id!==state.user.id)return shell('<div class="notice">Only the business owner can edit this profile.</div>');return shell(`<div class="workspace-heading"><span class="eyebrow">BUSINESS PROFILE</span><h1 class="page-title">Personalize ${e(p.name)}</h1><p class="subtle">Your profile photos and cover art help customers recognize your actual business. Changes are saved to your local AVORA data.</p></div><div class="panel profile-editor"><div class="photo-editor"><div class="avatar avora-avatar-large">${businessAvatar(p)}</div><div><strong>Business profile photo or logo</strong><p class="subtle">JPG, PNG or WebP · up to 2.2 MB</p><input type="file" id="business-avatar" accept="image/png,image/jpeg,image/webp"><button class="btn outline small" data-action="upload-business-image" data-kind="provider-avatar" data-id="${pid}" data-input="business-avatar">Upload profile photo</button></div></div><div class="photo-editor"><img class="business-cover-preview" src="${e(providerImage(p))}" alt="Current business cover"><div><strong>Business cover photo</strong><p class="subtle">Use an authentic image of your work, store or portfolio.</p><input type="file" id="business-cover" accept="image/png,image/jpeg,image/webp"><button class="btn outline small" data-action="upload-business-image" data-kind="provider-cover" data-id="${pid}" data-input="business-cover">Upload cover</button></div></div><form data-form="business-edit" data-provider="${pid}"><div class="form-section"><span class="eyebrow">IDENTITY</span><div class="split"><div class="field"><label>Business name</label><input name="name" value="${e(p.name)}" required></div><div class="field"><label>Category</label><input name="category" value="${e(p.category)}" required></div></div><div class="field"><label>Offering type</label><select name="kind" data-adapt-kind>${kindOptions(p.kind)}</select></div></div><div class="form-section"><span class="eyebrow">LOCATION & DELIVERY</span><div class="split"><div class="field"><label>City</label><input name="city" value="${e(p.city)}" required></div><div class="field"><label>Country</label><input name="country" value="${e(p.country)}" required></div></div><label class="subtle"><input type="checkbox" name="remote" ${p.remote?'checked':''}> Available remotely</label>${providerExtraFields(p)}</div><div class="form-section"><span class="eyebrow">SERVICES & PRICING</span><div class="field"><label>About your business</label><textarea name="bio" required minlength="10">${e(p.bio)}</textarea></div><div class="field"><label>Skills and specialties</label><input name="skills" value="${e(p.skills)}" required></div><div class="split"><div class="field"><label class="price-label">Starting price (USD demo)</label><input name="price" type="number" min="0" value="${p.price}" required></div><div class="field"><label class="capacity-label">Available capacity</label><input name="capacity" type="number" min="1" value="${p.capacity}" required></div></div></div><div class="form-actions"><button class="btn">Save business changes</button><a href="#/market/${pid}/manage" class="btn outline">Manage listings</a><a href="#/provider/${pid}" class="btn ghost">View profile</a></div></form></div>`) }
function editAccount(){if(!state.user)return mustSign();const u=state.user;return shell(`<div class="workspace-heading"><span class="eyebrow">MY AVORA IDENTITY</span><h1 class="page-title">Your profile</h1><p class="subtle">Choose how your name, bio and profile photo appear to other participants.</p></div><div class="panel profile-editor"><div class="photo-editor"><div class="avatar avora-avatar-large">${userAvatar(u)}</div><div><strong>Profile photo</strong><p class="subtle">Upload an image of yourself or a permitted illustration; no photo is required.</p><input type="file" id="user-avatar" accept="image/png,image/jpeg,image/webp"><button class="btn outline small" data-action="upload-account-image" data-id="${u.id}" data-input="user-avatar">Upload photo</button></div></div><form data-form="account-edit"><div class="field"><label>Display name</label><input name="name" value="${e(u.name)}" minlength="2" required></div><div class="field"><label>City (optional)</label><input name="city" value="${e(u.city||'')}"></div><div class="field"><label>About you</label><textarea name="bio" maxlength="420" placeholder="A little about you and your interests…">${e(u.bio||'')}</textarea></div><div class="form-actions"><button class="btn">Save profile</button><a href="#/settings" class="btn ghost">Settings</a></div></form></div>`) }

function messages(){if(!state.user)return mustSign();const mine=state.requests.filter(r=>r.mine||r.buyer_id===state.user.id);return shell(`<h1 class="page-title">Messages & projects</h1><p class="subtle">Conversations are linked to a request and accessible only to the buyer and participating providers.</p><div class="panel">${mine.map(r=>`<div class="list-item"><div><b>${e(r.title)}</b><p class="meta">${e(r.status)} · ${e(r.city)}</p></div><a href="#/requests/${r.id}" class="btn ghost small">Open chat</a></div>`).join('')||'<p class="subtle">Open a project workspace to message participating providers.</p>'}</div>`)}
function settings(){if(!state.user)return mustSign();return shell(`<h1 class="page-title">Settings</h1><p class="subtle">Your account, preferences, accessibility and security.</p><div class="split"><div class="panel"><h3>Account</h3><a class="btn outline small" href="#/me/edit">Edit photo and profile</a><p><b>${e(state.user.name)}</b><br><span class="subtle">${e(state.user.email)}</span></p><p class="subtle">One account controls Buyer and Provider workspace access.</p><label class="field"><span class="subtle">Default workspace</span><select id="workspace-setting"><option value="buyer" ${state.mode==='buyer'?'selected':''}>Buyer</option><option value="provider" ${state.mode==='provider'?'selected':''}>Provider</option></select></label></div><div class="panel"><h3>Accessibility</h3><p class="subtle">Keyboard navigation, readable labels and responsive layouts are supported. More assistive and language options are planned.</p><label><input id="reduce-motion" type="checkbox"> Reduce animations</label></div><div class="panel"><h3>Privacy and trust</h3><p class="subtle">Sensitive documents and payment credentials are never displayed publicly. Do not use real personal data in this local prototype.</p><a class="link" href="#/privacy">Read privacy notice →</a></div><div class="panel"><h3>Security</h3><p class="subtle">Passwords are salted and hashed. Sessions are temporary. Production requires HTTPS, rate limiting, email verification and managed identity checks.</p><button class="btn outline" data-action="logout">Sign out</button></div></div>`)}
function trust(){return `<div class="page narrow"><span class="eyebrow">AVORA GUARDIAN</span><h1 class="page-title">Trust should be earned, not assumed.</h1><p class="subtle">Guardian connects evidence, verified payment states, transparent reviews and fair reporting procedures. A warning does not establish guilt.</p><div class="split"><div class="panel"><h3>Payment checks</h3><p class="subtle">NEAR testnet direct transfers are checked against blockchain RPC evidence. AVORA never claims payment until the transaction recipient, amount, signer and outcome match the approved coalition.</p></div><div class="panel"><h3>Verified feedback</h3><p class="subtle">Verified-payment reviews are planned but not yet available. Seeded example ratings are clearly demonstration records.</p></div><div class="panel"><h3>Report an issue</h3>${state.user?`<form data-form="report"><div class="field"><label>Type</label><select name="target_type"><option value="provider">Provider</option><option value="request">Request</option><option value="user">User</option></select></div><div class="field"><label>Referenced ID</label><input name="target_id" type="number" min="1" required></div><div class="field"><label>What happened?</label><textarea name="reason" minlength="12" required></textarea></div><button class="btn">Submit report</button></form>`:'<p class="subtle">Sign in to report a concern.</p><a class="btn ghost" href="#/signin">Sign in</a>'}</div><div class="panel"><h3>Responsible moderation</h3><p class="subtle">Reports remain open for accountable human review. This demo does not automatically suspend accounts or adjudicate disputes.</p></div></div></div>`}
function legal(kind){return `<div class="page narrow"><span class="eyebrow">POLICIES & TRANSPARENCY</span><h1 class="page-title">${kind==='terms'?'Terms & Conditions':'Privacy Notice'}</h1><p class="notice">Prototype policy summary for evaluation only. Not a production legal agreement; obtain qualified legal review before public launch.</p><div class="panel prose">${kind==='terms'?`<h3>1. Platform purpose</h3><p>AVORA is a prototype community marketplace for goods, services, freelance opportunities and collaborations. All seeded provider profiles and historical ratings are fictional.</p><h3>2. Accounts</h3><p>Users are responsible for providing accurate information and protecting their account credentials. A shared account may have Buyer and Provider modes, but access is controlled on the server.</p><h3>3. Transactions and provider responsibilities</h3><p>Only user-approved NEAR testnet transfer verification is supported; USD catalogue prices are illustrative and not converted into NEAR payments. Parties agree to scope separately. AVORA is not an escrow provider.</p><h3>4. Trust and disputes</h3><p>Reports are evidence to be reviewed, not proof of misconduct. Production moderation and appeal procedures require operational staffing and further implementation.</p><h3>5. Limitations</h3><p>This demonstration is provided as-is for technical review; do not use it to conduct real commerce.</p>`:`<h3>1. Information in this demonstration</h3><p>Accounts store a name, email, salted password hash and temporary session tokens in local SQLite. Project requests, proposals, messages and reports are also stored locally.</p><h3>2. Usage</h3><p>Data is used to demonstrate community workflows and verify access permissions. No advertising profiling or external analytics is included.</p><h3>3. Payment processing</h3><p>NEAR testnet public account IDs, approved allocations, transaction hashes and verification outcomes are stored locally. AVORA does not store wallet secret keys.</p><h3>4. Before production</h3><p>Implement consent management, data subject request handling, retention, breach response, access logging, security testing and appropriate cross-border safeguards.</p>`}</div></div>`}
function about(){return `<div class="page narrow"><span class="eyebrow">OUR APPROACH</span><h1 class="page-title">Local roots. Global possibilities.</h1><div class="panel prose"><h3>Not another product-only marketplace</h3><p>AVORA connects everyday customers, skilled workers, small businesses and remote freelancers. A single profile can switch between Buyer and Provider workspaces.</p><h3>Opportunity Assembly</h3><p>When one provider cannot fulfil a request, AVORA proposes capacity-aware partnerships. Providers remain independent and decide whether to participate.</p><h3>Fifth Industrial Revolution values</h3><p>Human oversight, accessible opportunity, economic resilience, clear consent and transparent tradeoffs guide our design.</p><h3>What is working today?</h3><p>Local accounts, provider profiles, search, service requests, quotations, proposal approvals, participant messaging, Guardian reports, deterministic coalition matching and optional AI explanation with verified NEAR testnet transfers.</p><h3>What is not production-ready?</h3><p>Real identity verification, distributed seller settlements, escrow, automated global shipping, comprehensive legal compliance and production moderation.</p></div></div>`}
function mustSign(){return `<div class="page narrow"><div class="panel"><h1 class="page-title">Sign in to continue</h1><p class="subtle">Browse listings freely. Sign in to post a request, manage your business or message participants.</p><a href="#/signin" class="btn">Sign in</a></div></div>`}
async function render(){const key=path().split('?')[0],parts=key.split('/').filter(Boolean);let body;if(key==='/')body=landing();else if(key==='/signup')body=signin(true);else if(key==='/signin')body=signin(false);else if(key==='/dashboard')body=state.user?dashboard():mustSign();else if(key==='/explore')body=explore();else if(key==='/market-bag')body=await marketBagView();else if(parts[0]==='market-order'&&parts[1])body=await marketNearOrder(parts[1]);else if(key==='/market-orders')body=await marketOrders();else if(key==='/operations')body=await operationsView();else if(parts[0]==='market'&&parts[1]&&parts[2]==='request')body=await marketRequest(parts[1],parts[3]);else if(parts[0]==='market'&&parts[1]&&parts[2]==='edit')body=await marketEdit(parts[1],parts[3]);else if(parts[0]==='market'&&parts[1]&&parts[2]==='product')body=await marketProduct(parts[1],parts[3]);else if(parts[0]==='market'&&parts[1]&&parts[2]==='manage')body=await marketManage(parts[1]);else if(parts[0]==='market'&&parts[1])body=await marketStore(parts[1]);else if(key==='/provider/new')body=providerForm();else if(key==='/me/edit')body=editAccount();else if(parts[0]==='provider'&&parts[1]&&parts[2]==='edit')body=await editBusiness(parts[1]);else if(parts[0]==='provider'&&parts[1]&&parts[2]==='message')body=startEnquiry(parts[1]);else if(parts[0]==='provider'&&parts[1])body=await profile(parts[1]);else if(key==='/requests/new')body=requestForm();else if(key==='/requests')body=requests();else if(key==='/near')body=state.user?shell(await nearView()):mustSign();else if(parts[0]==='requests'&&parts[1])body=await detailRequest(parts[1]);else if(key==='/messages')body=await enquiryList();else if(parts[0]==='enquiry'&&parts[1])body=await enquiryConversation(parts[1]);else if(parts[0]==='shop'&&parts[1]&&parts[2]==='product')body=await shopProduct(parts[1],parts[3]);else if(parts[0]==='shop'&&parts[1])body=await shopPage(parts[1]);else if(key==='/sample-bag')body=demoBagView();else if(key==='/settings')body=settings();else if(key==='/terms')body=legal('terms');else if(key==='/privacy')body=legal('privacy');else if(key==='/trust')body=trust();else if(key==='/about')body=about();else body='<div class="page">Page not found</div>';const bnav=key==='/'?'':avoraBackRoute(key);const backBar=bnav?`<nav class="avora-backbar" aria-label="Return navigation"><a class="avora-back-button" href="${e(bnav.url)}">← ${e(bnav.text)}</a></nav>`:'';$('#app').innerHTML=header()+backBar+body+foot();document.title='AVORA · '+(parts[0]||'Community commerce');syncServiceFields()}
async function submit(ev){const form=ev.target;if(!form.matches('form[data-form]'))return;ev.preventDefault();const type=form.dataset.form;const d=Object.fromEntries(new FormData(form));let out;try{const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;
if(type==='signin'||type==='signup'){out=await api('/auth/'+(type==='signup'?'register':'login'),{method:'POST',body:JSON.stringify(d)});state.token=out.token;sessionStorage.setItem('avora_token',out.token);await refresh();go('/dashboard')}
else if(type==='search'){state.q=d.q||'';if(location.hash==='#/explore'){state.providers=await api('/providers?q='+encodeURIComponent(state.q)+'&sort='+encodeURIComponent(d.sort||'recommended'));await render()}else go('/explore')}
else if(type==='request'){out=await api('/requests',{method:'POST',body:JSON.stringify({...d,budget:+d.budget,quantity:+d.quantity,remote:!!d.remote})});await refresh();go('/requests/'+out.id)}
else if(type==='provider'){out=await api('/providers',{method:'POST',body:JSON.stringify({...d,price:+d.price,capacity:+d.capacity,remote:!!d.remote})});await refresh();toast('Business created. Add products or services to your storefront.');go('/market/'+out.id+'/manage')}
else if(type==='proposal'){out=await api('/requests/'+form.dataset.request+'/proposals',{method:'POST',body:JSON.stringify({...d,provider_id:+d.provider_id,amount:+d.amount})});await render();toast('Quote submitted.')}
else if(type==='message'){await api('/requests/'+form.dataset.request+'/messages',{method:'POST',body:JSON.stringify(d)});await render()}
else if(type==='fashion-search'){shopState.q=d.q||'';shopState.category=d.category||'All';shopState.sort=d.sort||'featured';await render()}
else if(type==='business-edit'){await api('/experience/providers/'+form.dataset.provider,{method:'PUT',body:JSON.stringify({...d,price:+d.price,capacity:+d.capacity,remote:!!d.remote})});await refresh();toast('Business profile updated.');go('/provider/'+form.dataset.provider)}
else if(type==='account-edit'){await api('/experience/me',{method:'PUT',body:JSON.stringify(d)});await refresh();toast('Profile saved.');go('/dashboard')}

else if(type==='enquiry-new'){out=await api('/providers/'+form.dataset.provider+'/enquiries',{method:'POST',body:JSON.stringify({subject:d.subject,message:d.message})});go('/enquiry/'+out.id);toast('Message request sent. The provider must accept before chat starts.')}
else if(type==='enquiry-reply'){await api('/enquiries/'+form.dataset.enquiry+'/messages',{method:'POST',body:JSON.stringify({body:d.body})});await render();toast('Message sent.')}
else if(type==='report'){out=await api('/reports',{method:'POST',body:JSON.stringify({...d,target_id:+d.target_id})});toast('Report #'+out.id+' recorded for review.');form.reset()}
}catch(err){toast('Could not complete: '+err.message)}finally{const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=false}}
async function act(ev){const b=ev.target.closest('[data-action]');if(!b)return;const id=+b.dataset.id;try{switch(b.dataset.action){case 'enquiry-decide':{await api('/experience/enquiries/'+id+'/decision',{method:'POST',body:JSON.stringify({decision:b.dataset.decision})});await render();toast('Message request '+b.dataset.decision+'.');break}case 'upload-business-image':{const file=document.getElementById(b.dataset.input)?.files?.[0];if(!file)throw Error('Select a photo first');await uploadPhoto(file,b.dataset.kind,id);await refresh();await render();toast('Business photo updated');break}case 'upload-account-image':{const file=document.getElementById(b.dataset.input)?.files?.[0];if(!file)throw Error('Select a photo first');await uploadPhoto(file,'user-avatar',id);await refresh();await render();toast('Profile photo updated');break}case 'fashion-reset':shopState.q='';shopState.category='All';shopState.sort='featured';await render();break;
case 'fashion-image':{const img=$('#fashion-main-photo');if(img)img.src=b.dataset.src;document.querySelectorAll('.fashion-thumb').forEach(x=>x.classList.toggle('active',x===b));break}
case 'demo-bag':go('/sample-bag');break;
case 'demo-bag-remove':demoBag.splice(Number(b.dataset.index),1);saveDemoBag();await render();break;
case 'demo-bag-add':{const pid=Number(b.dataset.provider);const detail=await api('/providers/'+pid);if(detail.name!=='VELORA FASHION'||detail.owner_id!=null)throw Error('This sample shop is not available for checkout');const l=(detail.listings||[]).find(x=>x.id===id);if(!l)throw Error('Style unavailable');const size=$('#fashion-size')?.value||'One size';const qty=Number($('#fashion-quantity')?.value||1);if(!Number.isSafeInteger(qty)||qty<1||qty>10)throw Error('Select a quantity from 1 to 10');const existing=demoBag.find(x=>x.id===id&&x.size===size);if(existing){if(existing.qty+qty>10)throw Error('Maximum 10 per sample item');existing.qty+=qty}else demoBag.push({id,title:l.title,price:l.price,size,qty});saveDemoBag();toast('Added to sample bag');await render();break}
case 'logout':try{await api('/auth/logout',{method:'POST'})}catch(err){}state.token='';state.user=null;sessionStorage.removeItem('avora_token');go('/');break;case 'profile':go('/provider/'+id);break;case 'accept':await api('/proposals/'+id+'/accept',{method:'POST'});await render();toast('Proposal accepted.');break;case 'assemble':{b.disabled=true;b.textContent='Analyzing…';const x=await api('/ai/assemble/'+id,{method:'POST'});const target=$('#intelligence');target.innerHTML=`<div class="notice ${x.missing_units?'':'good'}">${x.covered_units}/${x.requested_units} units covered · Estimated $${x.estimated_total_usd} USD · ${x.fits_budget?'within budget':'exceeds budget'}</div>${x.plan.map(p=>`<div class="list-item"><div><b>${e(p.name)}</b><p class="meta">${p.units} unit(s) · $${p.subtotal_usd} illustrative cost</p></div></div>`).join('')}<div class="avora-ai-markdown">${window.avoraFormatAI(x.assistant.text)}</div><p class="hint">Analysis: ${e(x.assistant.mode)}. Nobody has accepted or been paid.</p>`;b.disabled=false;b.textContent='Recalculate';break}case 'guardian':{const x=await api('/ai/guardian/'+id,{method:'POST'});$('#guardian').innerHTML=`<div class="notice">${e(x.assessment)}</div><div class="avora-ai-markdown">${window.avoraFormatAI(x.assistant.text)}</div>`;break}case 'review':{const score=prompt('Rating from 1 to 5');if(!score)return;const text=prompt('Describe your completed transaction (minimum eight characters)');if(!text)return;await api('/reviews',{method:'POST',body:JSON.stringify({payment_id:id,score:+score,text})});toast('Verified payment review created.');break}case 'report':go('/trust');break}
}catch(err){toast(err.message)}}
document.addEventListener('submit',submit);document.addEventListener('click',act);document.addEventListener('change',ev=>{if(ev.target.matches('[data-adapt-kind]'))syncServiceFields();if(ev.target.id==='workspace'||ev.target.id==='workspace-setting'){state.mode=ev.target.value;localStorage.setItem('avora_mode',state.mode);render()}if(ev.target.id==='reduce-motion'){document.documentElement.style.scrollBehavior=ev.target.checked?'auto':'smooth'}});window.addEventListener('hashchange',render);
(async()=>{await refresh();await render()})();
